const R=Resus, $=id=>document.getElementById(id), KEY='resus-pocket-v1';
let logScope='all',checklistDisplay='items';
let s,tab='live',checklist='arrest',checkReturn='live',sheetContext=null,toastTimeout,installPrompt=null,storageOK=true,wakeLock=null,liveCheckIndex=0;
s=R.fresh();
if(s.phase==='Active'&&s.deadline===null)s.deadline=Date.now()+Math.max(0,s.remaining);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function clock(ms){const sec=Math.max(0,Math.floor(ms/1000)),h=Math.floor(sec/3600);return (h?h.toString().padStart(2,'0')+':':'')+Math.floor(sec%3600/60).toString().padStart(2,'0')+':'+(sec%60).toString().padStart(2,'0');}
function countdown(ms){return clock(Math.ceil(Math.max(0,ms)/1000)*1000);}
function time(at){return new Date(at).toLocaleTimeString('en-NZ',{hour12:false,hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function local(at){const d=new Date(at);return new Date(at-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function save(){if(window.notesEquipmentMode)parent.postMessage({type:'notes-equipment-state',session:s},location.origin);else if(window.notesArrestReady)parent.postMessage({type:'notes-arrest-state',session:s},location.origin);}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').classList.remove('show'),4000);}
function commit(fn,message){R.snapshot(s);fn();save();render();if(message)toast(message);}
function finished(){return s.phase==='Ended';}
function canRecord(){if(finished()){toast('Session ended. Undo the end action to continue.');return false;}return true;}
function torsades(){return R.hasTorsades(s);}
function drugDose(type){const d=R.dose(s),c=R.counts(s);return !d?null:type==='adrenaline'?d.adr:c.amio===0?d.amio1:d.amio2;}
function drugCard(type){const adr=type==='adrenaline',name=adr?'Adrenaline':'Amiodarone',d=R.dose(s),c=R.counts(s),value=drugDose(type),blocked=!adr&&torsades(),canRef=d&&!s.special&&!blocked&&(adr||c.amio<2)&&!['ROSC','Ended'].includes(s.phase);
return `<section class="drug" id="${type}Card"><h3>${name}</h3><div class="drug-dose ${R.isPaediatric(s)&&d?'child':''}">${d?esc(value+' mg IV'):'Enter weight'}</div><strong class="drug-clock" id="${type}Clock">—</strong><p class="caption" id="${type}Status"></p><button class="record" data-drug="${type}" ${canRef?'':'disabled'}>${canRef?'Record '+value+' mg IV':blocked?'Withhold · torsades':s.special?'Manual review':!adr&&c.amio>=2?'2 doses recorded':s.phase==='ROSC'?'ROSC recorded':s.phase==='Ended'?'Session ended':'Weight needed'}</button><div class="drug-links"><button class="administration-link" data-drug-info="${type}" aria-label="${name} administration guidance">Administration ⓘ</button><button class="alternate" data-custom-drug="${type}" aria-label="Other ${name.toLowerCase()} dose, route or time">Other…</button></div></section>`;}
function liveChecklist(){
 const list=ARREST_CHECKLISTS[0],done=list.items.filter((_,i)=>checkStatus('arrest:'+i)?.checked).length;
 liveCheckIndex=Math.max(0,Math.min(list.items.length-1,liveCheckIndex));const key='arrest:'+liveCheckIndex,e=checkStatus(key);
 return `<section class="live-checklist" aria-label="Cardiac arrest checklist"><div class="live-check-heading"><button data-action="arrest-checklist">☑ Arrest checklist</button><span>${done}/${list.items.length}</span><div><button data-check-step="-1" aria-label="Previous checklist item" ${liveCheckIndex===0?'disabled':''}>‹</button><button data-check-step="1" aria-label="Next checklist item" ${liveCheckIndex===list.items.length-1?'disabled':''}>›</button></div></div><label class="live-check-item"><input type="checkbox" aria-label="${esc(list.items[liveCheckIndex])}" data-check="${key}" ${e?.checked?'checked':''} ${finished()?'disabled':''}><span><small>${liveCheckIndex+1}. </small>${esc(list.items[liveCheckIndex])}${e?.checked?`<time>${time(e.at)}</time>`:''}</span></label></section>`;
}
function weightHeader(){const w=s.weight,j=R.joules(w);return `<div class="weight-row"><button data-action="weight" class="weight-button" aria-label="Patient weight${w?' '+esc(w)+' kg':''}"><span>Pt weight (kg)</span><strong>${w?esc(w)+' kg':'Enter kg'}</strong>${w?`<small class="header-energy" title="4 J/kg · maximum 200 J">${j} J${s.weightSource.startsWith('Estimated')?' · est.':''}</small>`:''}</button>${R.needsPaediatricPads(w)?'<div class="pads-prompt"><span aria-hidden="true">▰ ▰</span> Use paediatric pads</div>':''}${s.special?'<span class="special-flag">Special situation · manual review</span>':''}</div>`;}
function cycleRecords(){return R.active(s).filter(e=>['start','shock','noshock','rearrest'].includes(e.type)).sort((a,b)=>a.at-b.at);}
function openCycleLog(){const rows=cycleRecords(),prior=s.priorShocks+s.priorNoShock;sheet('Cycle log',`${prior?`<p class="caption">${prior} earlier cycles recorded as counts only; individual timestamps unavailable.</p>`:''}${rows.length?rows.map((e,i)=>`<article class="cycle-log-row"><b>${e.preApp?'Before app':'Cycle '+(prior+rows.slice(0,i+1).filter(x=>!x.preApp).length)}</b><time>${e.timeUnknown?'Time not set':time(e.at)}</time><p>${e.type==='shock'?'<svg class="shock-bolt" viewBox="0 0 24 32" aria-hidden="true"><path d="M14 1 1 19h9l-1 12 14-20h-9z"/></svg> Shock delivered':e.type==='noshock'?'No shock · next cycle started':e.type==='rearrest'?'Re-arrest · CPR restarted':'CPR cycle started'}${e.details?' · '+esc(e.details):''}</p></article>`).join(''):'<p>No cycles recorded yet.</p>'}`);}
function liveView(){const c=R.counts(s),w=s.weight,stopped=['ROSC','Ended'].includes(s.phase),j=R.joules(w);return `<div class="live-dashboard">

<section class="timer-panel" id="timerPanel"><div class="cycle-dial" id="cycleTrack"><svg class="cycle-ring" width="100%" height="100%" aria-hidden="true"><rect class="ring-track"/><rect class="ring-fill" id="progress" pathLength="120"/></svg><div class="dial-face"><button class="cycle-heading" data-action="cycle-log" aria-label="Open timestamped cycle log"><span id="cycleTitle">${s.cycle?'CPR cycle '+s.cycle:'Ready for CPR'}</span><span class="dial-shocks"><svg class="shock-bolt" viewBox="0 0 24 32" aria-hidden="true"><path d="M14 1 1 19h9l-1 12 14-20h-9z"/></svg><strong>${c.shocks}</strong><span>${c.shocks===1?'shock':'shocks'}</span></span></button><button class="previous-shock" data-action="previous-shock" aria-label="Add a shock before app start">+ Previous shock</button><div class="countdown" id="cycleClock" role="timer" aria-label="Time remaining in CPR cycle">02:00</div><div class="cycle-caption" id="cycleCaption">Ready to start</div><div class="dial-actions"><button class="unexpected-rosc" data-outcome="rosc" id="unexpectedRosc" aria-label="Record unexpected ROSC" ${!['Ready','Active'].includes(s.phase)?'hidden':''}>♡ ROSC</button><button class="start-button" data-action="${stopped?(s.phase==='ROSC'?'rearrest':'export'):'start'}" id="startCycle" ${s.phase==='Active'?'hidden':''}>${stopped?(s.phase==='ROSC'?'Re-arrest · restart CPR':'Export record'):'▶ Start CPR'}</button><button class="rhythm-check-button" data-action="rhythm-check" id="rhythmCheck" hidden>⌁ Rhythm check</button></div></div></div><span class="sr-only" id="cycleAlert" role="status" aria-live="polite"></span></section>
<div class="access-cards"><button data-action="airway"><svg class="equipment-icon" viewBox="0 0 32 32" aria-hidden="true"><path d="M16 3v12m0-5-4 4m4-4 4 4M12 9C7 9 3 17 3 24c0 4 3 4 6 2l4-3V11M20 9c5 0 9 8 9 15 0 4-3 4-6 2l-4-3V11"/></svg><span>Airway</span><span class="card-chevron" aria-hidden="true">›</span></button><button data-action="access"><svg class="equipment-icon" viewBox="0 0 32 32" aria-hidden="true"><path d="M10 3h12v17a6 6 0 0 1-12 0V3ZM8 7h16M10 13h12M13 1v4m6-4v4m-3 21v5"/><path d="M16 17v4"/></svg><span>Access</span><span class="card-chevron" aria-hidden="true">›</span></button></div><div class="drug-grid">${drugCard('adrenaline')}${R.careMode(s)==='amiodarone'?drugCard('amiodarone'):supportCard(R.careMode(s))}</div>
${s.phase==='ROSC'?'<button class="postrosc-main" data-action="postrosc">☑ Post ROSC checklist</button>':''}
<div class="tools-row"><button data-action="interventions" ${finished()?'disabled':''}><span aria-hidden="true">＋</span> Airway / access</button><button data-action="note" ${finished()?'disabled':''}>+ Event</button></div></div>`;}
const CAUSES=[
{id:'oxygen',group:'4 Hs',name:'Hypoxia',plain:'Low oxygen',text:'Review airway patency, oxygen supply, ventilation and waveform capnography.'},
{id:'volume',group:'4 Hs',name:'Hypovolaemia',plain:'Low circulating volume',text:'Consider bleeding or fluid loss. Look for the cause and review volume replacement in the applicable CPG.'},
{id:'metabolic',group:'4 Hs',name:'Hypo / hyperkalaemia',plain:'Potassium or metabolic disturbance',text:'Consider renal failure, dialysis, medicines and other metabolic causes. Review relevant history, ECG and available point-of-care results.'},
{id:'temperature',group:'4 Hs',name:'Hypo / hyperthermia',plain:'Low or high body temperature',text:'Review exposure and core temperature if available. Temperature-related arrest can require a modified approach; use the specific CPG.'},
{id:'tension',group:'4 Ts',name:'Tension pneumothorax',plain:'Pressure in the chest',text:'Consider the history, chest findings and ventilation difficulty. Use the specific CPG for assessment and treatment.'},
{id:'tamponade',group:'4 Ts',name:'Cardiac tamponade',plain:'Pressure around the heart',text:'Consider trauma and other relevant history. Use ultrasound only if available, within scope, and without interrupting CPR.'},
{id:'toxins',group:'4 Ts',name:'Toxins',plain:'Poisoning or medicines',text:'Ask about medicines, substances, overdose and scene clues. Seek the relevant toxicology guidance.'},
{id:'thrombosis',group:'4 Ts',name:'Thrombosis',plain:'Coronary or pulmonary clot',text:'Consider myocardial infarction or pulmonary embolism from the history and findings. Use the relevant CPG and specialist advice.'}
];
function causeState(id){return R.active(s).filter(e=>e.type==='cause'&&e.cause===id).at(-1);}
function causesView(){return `<h2>Reversible causes</h2><p class="page-intro">4 Hs and 4 Ts. Open a cause for a short prompt. Marking a review does not rule a cause out.</p>${['4 Hs','4 Ts'].map(g=>`<h3 class="cause-group">${g}</h3>${CAUSES.filter(c=>c.group===g).map(c=>{const e=causeState(c.id);return `<details class="cause" data-cause-id="${c.id}" data-status="${e?.status||''}"><summary>${c.name}<span class="cause-status">${e?esc(e.status==='treated'?'Action recorded':e.status==='considered'?'Reviewed':'Suspected'):''}</span></summary><b class="muted">${c.plain}</b><p>${c.text}</p><div class="cause-actions">${[['considered','Reviewed'],['suspected','Suspected'],['treated','Record action']].map(([v,l])=>`<button data-cause="${c.id}" data-status="${v}" ${finished()?'disabled':''}>${l}</button>`).join('')}</div>${e?`<p class="caption">${time(e.at)} · ${esc(e.details)}</p>`:''}</details>`;}).join('')}`).join('')}<p class="caption">ANZCOR 4 Hs / 4 Ts · <a href="https://www.anzcor.org/home/adult-advanced-life-support/guideline-11-2-protocols-for-adult-advanced-life-support" target="_blank" rel="noopener">Full guideline ↗</a></p>`;}
function checkStatus(key){return R.active(s).filter(e=>e.type==='checklist'&&e.key===key).at(-1);}
function checksView(){const list=ARREST_CHECKLISTS.find(c=>c.id===checklist),done=list.items.filter((_,i)=>checkStatus(checklist+':'+i)?.checked).length;return `<button class="check-back" data-tab="${checkReturn}">← Back</button><div class="row"><h2>${list.label}</h2><span class="muted">${done}/${list.items.length}</span></div><p class="caption">${list.code} · Each tick is timestamped.${list.intro?' '+list.intro:''}</p><div class="panel" style="padding:0">${list.items.map((t,i)=>{const key=list.id+':'+i,e=checkStatus(key);return `<label class="check-item"><input type="checkbox" aria-label="${esc(t)}" data-check="${key}" ${e?.checked?'checked':''} ${finished()?'disabled':''}><span>${esc(t)}${e?.checked?`<time>${time(e.at)}</time>`:''}</span></label>`;}).join('')}</div><a href="${list.pdf}" target="_blank" rel="noopener">Original ${formatGuidelineReference(list.code.split(' · ')[0])} ↗</a><p class="caption">A tick records checklist review, not administration or an intervention.</p>`;}
function logRows(includeVoided=true){return R.logEntries(s,ARREST_CHECKLISTS,{scope:logScope,checklists:checklistDisplay,includeVoided});}
function logView(){const rows=logRows();return `<div class="row"><h2>Event log</h2><button data-action="copy" aria-label="Export event log to clipboard">Export</button></div><div class="log-filters"><label>Show<select id="logScope"><option value="all" ${logScope==='all'?'selected':''}>All events</option><option value="interventions" ${logScope==='interventions'?'selected':''}>Interventions only</option></select></label><label>Checklists<select id="checklistDisplay" ${logScope==='interventions'?'disabled':''}><option value="items" ${checklistDisplay==='items'?'selected':''}>Each item</option><option value="times" ${checklistDisplay==='times'?'selected':''}>Start & finish only</option></select></label></div><p class="caption log-filter-help">${logScope==='interventions'?'CPR, shocks, rhythm checks, medicines, airway/access and recorded actions. Checklist items excluded.':checklistDisplay==='times'?'Checklist start: first item checked. Finish: all items checked. Other events remain visible.':'All recorded events, including individual checklist items.'} Export copies this view; voided entries are excluded.</p><p class="caption">${new Date(s.appStart).toLocaleDateString('en-NZ')} · ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}<br>Resus start ${time(s.resusStart)}${s.resusStart<s.appStart?' · before app opened':''} · ${s.phase}</p><button class="primary" data-action="note" ${finished()?'disabled':''}>+ Add event / earlier event</button>${rows.length?rows.slice().reverse().map(e=>`<article data-event-type="${e.type==='equipment'&&['iv','io'].includes(e.procedure)?'access':e.type}" class="log-entry ${e.voided?'void':''}"><time>${e.timeUnknown?'Before app':time(e.at)}${e.timeUnknown?'<small>Time not set</small>':`<small>${e.at<s.resusStart?'−':'+'}${clock(Math.abs(e.at-s.resusStart))} resus</small>`}</time><div>${e.type==='shock'?'<svg class="shock-bolt" viewBox="0 0 24 32" aria-hidden="true"><path d="M14 1 1 19h9l-1 12 14-20h-9z"/></svg>':''}<b>${esc(e.title)}</b><p>${esc(e.details)}</p>${e.needsReview&&!e.voided?`<button class="review-shock" data-edit="${esc(e.id)}">Add time / edit details</button>`:''}${e.correctedAt?'<small class="caption">Corrected</small>':''}${e.voided?'<small class="caption">Voided · excluded from counts</small>':''}</div>${e.synthetic?`<button data-review-checklist="${esc(e.checklistId)}" aria-label="Review ${esc(e.title)}">↗</button>`:`<button data-edit="${esc(e.id)}" aria-label="Edit ${esc(e.title)} at ${e.timeUnknown?'time not set':time(e.at)}">✎</button>`}</article>`).join(''):'<p class="empty">No events in this view yet.</p>'}`;}
function render(){document.body.classList.toggle('large',s.largeText);document.body.classList.toggle('live-mode',tab==='live');document.body.classList.toggle('guidance-mode',tab==='guidance');document.body.classList.toggle('checklist-mode',tab==='checks');$('headerWeight').innerHTML=weightHeader();$('main').innerHTML=tab==='live'?liveView():tab==='guidance'?guidanceGrid():tab==='checks'?checksView():logView();document.querySelectorAll('[data-tab]').forEach(b=>{if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if($('undo'))$('undo').disabled=!s.undo.length;normalizeGuidelineReferences($('main'));normalizeGuidelineReferences($('headerWeight'));tick();}
function tick(){const t=R.timing(s),c=R.counts(s);$('appClock').textContent=clock(t.app);$('resusClock').textContent=clock(t.resus);document.querySelector('.bottom-nav [data-checklist=arrest]').classList.toggle('checklist-attention',R.checklistPrompt(s));$('appClock').classList.toggle('long-clock',t.app>=3600000);$('resusClock').classList.toggle('long-clock',t.resus>=3600000);if(tab!=='live')return;
 const on=s.phase==='Active',running=on&&s.deadline!==null,due=on&&t.left===0,stopped=['ROSC','Ended'].includes(s.phase);
 $('cycleClock').textContent=stopped?(s.phase==='ROSC'?'ROSC':'Ended'):countdown(t.left);$('cycleTitle').textContent=stopped?(s.phase==='ROSC'?'ROSC recorded':'Session ended'):s.cycle?'CPR cycle '+s.cycle:'Ready for CPR';$('cycleCaption').textContent=stopped?'Recorded at '+time(s.end):due?'Rhythm check due'+(t.late>1000?' · +'+clock(t.late):''):on&&!running?'Paused · resus clock continues':running&&t.left<=15000?'Prepare for rhythm check':running&&t.left<=30000?'30 seconds remaining':running?'CPR in progress':'Ready to start';
 if($('cycleAlert').textContent!==(due?'Cycle complete. Rhythm check.':''))$('cycleAlert').textContent=due?'Cycle complete. Rhythm check.':'';$('timerPanel').classList.toggle('due',due);$('timerPanel').classList.toggle('prepare',running&&t.left>0&&t.left<=15000);$('timerPanel').classList.toggle('stopped',stopped);$('timerPanel').classList.toggle('ready',s.phase==='Ready');$('progress').style.strokeDashoffset=String(120*(1-Math.max(0,Math.min(1,t.left/R.CYCLE))));$('unexpectedRosc').hidden=!['Ready','Active'].includes(s.phase);$('rhythmCheck').hidden=!due;$('cycleTrack').hidden=false;$('startCycle').hidden=on;
 const enabled=on&&!s.special;
 $('adrenalineClock').textContent=t.adr===null?'—':t.adr<0?'+'+clock(-t.adr):countdown(t.adr);
 $('adrenalineStatus').textContent=!enabled?'Review inactive':t.adr===null?'No dose recorded':t.adr<0?'4 min elapsed · review':'Until 4 min review';
 $('adrenalineCard').classList.toggle('attention',enabled&&t.adr!==null&&t.adr<=30000);
 if(R.careMode(s)==='amiodarone'){
 $('amiodaroneClock').textContent=t.amio===null?'—':clock(t.amio);
 const amioDue=enabled&&!torsades()&&['VF','VT'].includes(s.rhythm)&&((c.shocks>=3&&c.amio===0)||(c.shocks>=6&&c.amio===1));
 $('amiodaroneStatus').textContent=torsades()?'Withhold · torsades':!enabled?'Review inactive':amioDue?'Review '+(c.amio?'second':'first')+' dose':c.amio>=2?'Since last dose':(t.amio===null?'Review at '+(c.amio?'6':'3')+' shocks':'Since last dose');
 $('amiodaroneCard').classList.toggle('attention',amioDue);
 }else tickSupport(R.careMode(s),enabled);
}
function sheet(title,html,ctx={}){if(typeof stopExplainMe==='function')stopExplainMe();$('sheet').className='';sheetContext=ctx;$('sheet').innerHTML=`<div class="sheet-heading"><h2 id="sheetTitle">${title}</h2><button data-close aria-label="Close dialog">×</button></div><div class="sheet-content">${html}<p id="sheetError" class="error" role="alert" hidden></p></div>`;normalizeGuidelineReferences($('sheet'));if(!$('sheet').open)$('sheet').showModal();$('sheet').scrollTop=0;}
function closeSheet(){if(typeof stopExplainMe==='function')stopExplainMe();$('sheet').close();$('sheet').className='';sheetContext=null;}
function error(message){$('sheetError').hidden=false;$('sheetError').textContent=message;}
function toggleField(name,label,values,value=''){return `<fieldset class="toggles"><legend>${label}</legend>${values.map(v=>`<label class="toggle"><input type="radio" name="${name}" value="${esc(v)}" aria-label="${esc(v)}" ${v===value?'checked':''}><span>${esc(v)}</span></label>`).join('')}</fieldset>`;}
function openRhythm(outcome){const labels={shock:'Record shock delivered',noshock:'Record no-shock cycle',rosc:'Record ROSC'},opts=outcome==='shock'?['VF','VT','Torsades']:outcome==='noshock'?['PEA','Asystole','Other','Unknown']:['Sinus rhythm','Organised rhythm','AF','Other','Unknown'];
 sheet(labels[outcome],`${outcome==='shock'?'<label>Energy delivered (J) · optional<input id="shockEnergy" type="number" inputmode="numeric" min="1" max="1000" value="'+(R.shockEnergy(s)??'')+'" placeholder="Not recorded"></label>':''}${outcome==='shock'?rhythmImages():`<div class="choice-grid">${opts.map(r=>`<button data-record-rhythm="${r}">${r==='VT'?'Pulseless VT':r}</button>`).join('')}</div>`}`,{kind:'rhythm',outcome,eventId:s.pendingRhythm?.outcome===outcome?s.pendingRhythm.id:null});}
function openWeight(){sheet('Patient weight',`<label>Weight (kg)<input id="weightInput" type="text" inputmode="decimal" value="${esc(s.weight)}" autocomplete="off"></label><div class="number-pad">${['1','2','3','4','5','6','7','8','9','.','0','⌫'].map(k=>`<button data-key="${k}" aria-label="${k==='⌫'?'Delete digit':k}">${k}</button>`).join('')}</div><details><summary>Estimate weight from age</summary><label>Age in years<input id="ageInput" type="number" inputmode="decimal" min="0.01" max="14" step="any" value="${esc(s.age)}"></label><button data-action="estimate">Use age estimate</button><p class="caption">Under 1 year: 5 kg. 1–10 years: (age + 4) × 2. 11–14: age × 3. CPG 7.2; estimates may underestimate. Excludes newborn resuscitation.</p></details><p id="weightBasis" class="caption">${esc(s.weightSource)}</p><p id="weightPadPrompt" class="pads-entry" ${R.needsPaediatricPads(s.weight)?'':'hidden'}>▰ ▰ Use paediatric pads · 100 J or less</p><button class="primary" data-action="save-weight">Use weight</button>`,{kind:'weight',source:s.weightSource,replaceWeight:!!s.weight});}
function openRhythmCheck(){if(!R.canRhythmCheck(s))return;sheet('Rhythm check',`<p class="caption">Choose the observed outcome.</p><div class="rhythm-outcomes"><button class="shock" data-outcome="shock"><span aria-hidden="true">ϟ</span><b>Shock</b><small>Record delivered</small></button><button data-outcome="noshock"><span aria-hidden="true">⊘</span><b>No shock</b></button><button class="rosc" data-outcome="rosc"><span aria-hidden="true">♡</span><b>ROSC</b></button></div>`);}
function openResusTime(){sheet('When did resus start?',`<p>The app session clock stays unchanged.</p><label>Resuscitation started<input id="resusStartInput" type="datetime-local" step="60" value="${local(s.resusStart)}" max="${local(s.appStart)}"></label><div class="choice-grid">${[5,10,15,20].map(m=>`<button data-earlier="${m}">${m} min<small>before app opened</small></button>`).join('')}</div><p class="caption">Resus duration is elapsed clock time from this start, including pauses. It freezes at ROSC or session end.</p><button class="primary" data-action="save-resus-time">Save start time</button>`);}
function openSettings(){sheet('Session & display',`<div class="stack"><button data-action="explain-me">Tutorial</button><button id="undo" ${s.undo.length?'':'disabled'}>↶ Undo last action</button><button data-action="large">${s.largeText?'✓ Larger text on':'Larger text'}</button><button data-action="wake">${wakeLock?'✓ Screen kept awake':'Keep screen awake'}</button><button data-action="install">Add to home screen</button><button data-action="history">Earlier shocks / doses / cycles</button><button data-action="resus-time">Edit resus start</button><button data-action="guidance">Clinical guidance & sources</button><button data-action="export">Export event log</button></div><label><input id="specialInput" type="checkbox" ${s.special?'checked':''}>Special situation · disable routine dose prompts</label><p class="caption">Use specific guidance for trauma, hypothermia, pregnancy, toxins and other special situations.</p><div class="stack"><button class="danger" data-action="end" ${finished()?'disabled':''}>End resuscitation session</button><button class="danger" data-action="new">New patient / clear session</button></div><p class="caption" id="offlineState">${navigator.onLine?'Online':'Offline'} · Draft in this Notes tab only. Closing and reopening cardiac arrest preserves the current session. Export before refreshing or starting a new patient.</p>`);}
function openHistory(){sheet('Events before this app',`<p class="caption">These counts are added to events logged here. They do not create administration timestamps.</p><label>Prior shocks<input id="priorShocks" type="number" inputmode="numeric" min="0" max="100" value="${s.priorShocks}"></label><label>Prior no-shock cycles · total<input id="priorNoShock" type="number" inputmode="numeric" min="0" max="100" value="${s.priorNoShock}"></label><label>Prior consecutive no-shock cycles since last shock<input id="priorStreak" type="number" inputmode="numeric" min="0" max="100" value="${s.priorStreak}"></label><label>Prior amiodarone doses<select id="priorAmio">${[0,1,2].map(n=>`<option ${s.priorAmio===n?'selected':''}>${n}</option>`).join('')}</select></label><button class="primary" data-action="save-history">Save earlier counts</button><button class="primary" data-custom-drug="adrenaline">Record an earlier adrenaline dose</button>`);}
function administration(type){if(['magnesium','fluids'].includes(type))return supportAdministration(type);const d=R.dose(s);sheet(type==='adrenaline'?'Adrenaline · reference':'Amiodarone · reference',`<p><b>${d?esc((type==='adrenaline'?d.adr+' mg IV':d.amio1+' mg IV first; '+d.amio2+' mg IV second')):'Enter child weight for reference'}</b></p><p class="caption">${d?formatGuidelineReference(d.basis):'Reference only'}</p>${type==='adrenaline'?'<p>NZCPG cardiac arrest: every 4 minutes. Adults and children rounded to 50 kg or more: IV bolus, undiluted.</p><p>Children rounded to 40 kg or less: dilute 1 mg to a total of 10 mL with 0.9% sodium chloride (0.1 mg/mL). Draw up the dose and give as an IV bolus.</p>':'<p>IV bolus, undiluted. For persistent VF / pulseless VT: first dose after 3 shocks, second after 6 shocks, including earlier shocks.</p><p><b>Withhold if torsades is present or has occurred.</b></p>'}<a href="${type==='adrenaline'?'https://cpg.stjohn.org.nz/tabs/medicines/page/adrenaline-eas':'https://cpg.stjohn.org.nz/tabs/medicines/page/amiodarone-eas'}" target="_blank" rel="noopener"><em>EAS guideline ${type==='adrenaline'?'14.3':'14.4'}</em> ↗</a><p class="caption">NZCPG EAS ${type==='adrenaline'?'14.3':'14.4'} and EAS 3.14. Reference values do not record administration.</p>`);}
function openDrug(type){const name=type==='adrenaline'?'Adrenaline':type==='amiodarone'?'Amiodarone':type==='magnesium'?'Magnesium':type==='fluids'?'0.9% sodium chloride':'',now=Date.now();sheet('Record '+(name||'medicine'),`<form id="drugForm"><label>Medicine<input name="name" value="${name}" required></label><div class="inline-two"><label>Actual dose<input name="dose" type="number" inputmode="decimal" min="0.001" step="any" required placeholder="Dose given"></label><label>Unit<select name="unit">${['mg','mcg','mmol','mL','g'].map(u=>`<option ${u===(type==='magnesium'?'mmol':type==='fluids'?'mL':'mg')?'selected':''}>${u}</option>`).join('')}</select></label></div>${toggleField('route','Route',['IV','IO','IM','Other'],['magnesium','fluids'].includes(type)?'IV':'')}<label>Given at<input name="at" type="time" step="60" value="${local(now).slice(11)}" required></label><label>Notes<input name="notes" placeholder="Optional"></label><button class="primary" type="submit">Record actual administration</button></form>${type==='amiodarone'&&torsades()?'<p class="error">Torsades has occurred. CPG advises withholding amiodarone. This form records an actual event, not a recommendation.</p>':''}`,{kind:'drug',type,at:now});}
function openInterventions(group){sheet(group==='airway'?'Airway':group==='access'?'Access':'Airway / access',`<div class="choice-grid">${Object.entries(ARREST_EQUIPMENT).filter(([k])=>!group||(group==='access'?['iv','io'].includes(k):!['iv','io'].includes(k))).map(([k,e])=>`<button data-equipment="${k}">${e.name}</button>`).join('')}</div>`,{kind:'interventions'});}
const COLOURS={iv:{24:'#f4cc28',22:'#439be0',20:'#ef99ba',18:'#68b88b',16:'#aeb2b3'},io:{Large:'#f4cc28',Medium:'#439be0',Small:'#ef99ba'},igel:{1:'#ef99ba',1.5:'#88c9ee',2:'#aeb2b3',2.5:'#fff',3:'#f4cc28',4:'#68b88b',5:'#ee9b43'}};
function colourSizes(type,values){return `<fieldset class="toggles size-options"><legend>${type==='iv'?'Cannula size':'Size'}</legend>${values.map(v=>`<label class="toggle"><input type="radio" name="size" aria-label="${v}${type==='iv'?'G':''}" value="${v}"><span style="--size-colour:${COLOURS[type]?.[v]||'#ccd9d3'}">${v}${type==='iv'?'G':''}</span></label>`).join('')}</fieldset>`;}
function sizeFields(type){const sizes=ARREST_EQUIPMENT[type].sizes;if(type==='iv')return colourSizes(type,sizes);
if(type==='intubation')return `<fieldset class="toggles tube-options"><legend>Tube size (mm)</legend><div class="tube-grid">${sizes.map(v=>`<label class="toggle"><input type="radio" name="size" value="${v}" aria-label="${v} mm"><span>${v}<small>mm</small></span></label>`).join('')}</div></fieldset>`;
return colourSizes(type,sizes);}
function sitePicker(type){return toggleField('side','Side',['Left','Right'])+toggleField('site','Location',ARREST_SITES[type]).replace('class="toggles"','class="toggles '+(type==='iv'?'iv-sites':'io-sites')+'"');}
function enhanceEquipment(){const form=$('equipmentForm');

 [...form.children].filter(el=>el.tagName==='LABEL'||el.tagName==='FIELDSET').forEach(el=>{let row=el;if(el.tagName==='LABEL'){row=document.createElement('div');el.before(row);row.append(el);}row.classList.add('entry-row');const badge=document.createElement('span');badge.className='row-confirm';badge.setAttribute('aria-hidden','true');badge.textContent='✓';row.append(badge);});
 form.addEventListener('input',equipmentFeedback);form.addEventListener('change',equipmentFeedback);
}
function equipmentFeedback(e){const row=e.target.closest('.entry-row');if(!row)return;const inputs=[...row.querySelectorAll('input,textarea,select')],values=inputs.filter(el=>!['radio','checkbox'].includes(el.type)||el.checked).map(el=>el.value.trim()),valid=values.some(Boolean)&&inputs.every(el=>!el.value||el.validity.valid);
 const was=row.classList.contains('has-entry');row.classList.toggle('has-entry',valid);if(valid&&!was){row.classList.remove('entry-pop');void row.offsetWidth;row.classList.add('entry-pop');}

}
function openEquipment(type){const now=Date.now();sheet(ARREST_EQUIPMENT[type].name,`<form id="equipmentForm">${type==='laryngoscopy'?toggleField('method','Laryngoscopy',['Video','Direct'])+'<div id="bladeChoices"><p class="caption">Choose video or direct to show blade sizes.</p></div>'+toggleField('forceps','Magill forceps',['Used','Not used'])+toggleField('view','View',['Grade I','Grade IIa','Grade IIb','Grade III','Grade IV','No view']):sizeFields(type)}${['iv','io'].includes(type)?sitePicker(type):''}${type==='intubation'?toggleField('adjunct','Introducer',['Bougie','Stylet'])+'<label>Length at lips (cm)<input name="lips" type="number" min="1" max="50" inputmode="decimal" step="any"></label><fieldset class="toggles"><legend>Confirmed with</legend>'+['Waveform capnography','Visualised through cords','Chest rise','Auscultation'].map(x=>`<label><input name="confirmation" type="checkbox" value="${x}">${x}</label>`).join('')+'</fieldset>':''}${type==='laryngoscopy'?'':toggleField('outcome','Outcome',['Successful','Unsuccessful'])}<label>Time<input name="at" type="time" step="60" required value="${local(now).slice(11)}"></label><label>Notes<textarea name="notes" placeholder="Optional"></textarea></label><div class="equipment-record-actions"><button class="primary" type="submit">Record ${ARREST_EQUIPMENT[type].name}</button>${type==='laryngoscopy'?'<button class="primary" type="submit" name="followUp" value="intubation">Record Laryngoscopy and add Intubation</button>':''}</div></form>`,{kind:'equipment',type,at:now});enhanceEquipment();}
function openNote(cause=null){const now=Date.now();sheet(cause?'Record action · '+CAUSES.find(c=>c.id===cause).name:'Record another event',`<form id="noteForm"><label>${cause?'Action taken':'Event'}<textarea name="text" required placeholder="What happened?"></textarea></label><label>Event time<input name="at" type="time" step="60" required value="${local(now).slice(11)}"></label><button class="primary" type="submit">Record event</button></form>${!cause?'<button class="primary" data-custom-drug="other">Record another medicine</button>':''}`,{kind:'note',cause,at:now});}
function guidance(){sheet('Guidance & sources',`<p><b>Standard non-traumatic cardiac arrest.</b> Clinician reference and event recorder. It does not detect a rhythm, operate a defibrillator or infer treatment.</p><p>NZCPG <em>EAS guideline 3.14</em>: two minute CPR cycles; adrenaline review every 4 minutes; amiodarone reviews at 3 and 6 VF / pulseless VT shocks. Weight references retain the source app’s 5 / 10 / 20 / 30 / 40 kg paediatric bands.</p><p>The 4 J/kg calculation is capped at 200 J. The adult CPG specifies maximum defibrillator setting. A no-shock cycle is counted only when recorded.</p><div class="stack">${[['Cardiac arrest · <em>EAS guideline 3.14</em>','https://cpg.stjohn.org.nz/tabs/guidelines/cardiac-eas/page/cardiac-arrest-eas'],['Post ROSC · <em>EAS guideline 3.15</em>','https://cpg.stjohn.org.nz/tabs/guidelines/cardiac-eas/page/treatment-following-rosc-eas'],['Paediatric equipment & doses · <em>EAS guideline 7.2</em>','https://cpg.stjohn.org.nz/tabs/guidelines/paediatrics-eas/page/paediatric-equipment-and-drug-doses-eas'],['RSI · <em>EAS guideline 9.3</em>','https://cpg.stjohn.org.nz/tabs/guidelines/intubation-and-ventilation/page/rsi-rapid-sequence-intubation-eas']].map(([l,p])=>`<a href="${p}" target="_blank" rel="noopener">${l} ↗</a>`).join('')}</div><details class="panel"><summary>RSI medicine references</summary><p>Fentanyl: 2 mcg/kg IV, maximum 200 mcg. Only when indicated for TBI, suspected intracranial pathology or hypertension; withhold with shock.</p><p>Ketamine: 2 mg/kg IV, maximum 200 mg. Consider 1 mg/kg with shock / prior sedation; do not reduce for prolonged seizures.</p><p>Rocuronium <b>or</b> suxamethonium: 2 mg/kg IV, maximum 200 mg. Adult dose usually rounded to nearest 50 mg. Alternatives, not both.</p><p>Use the full RSI CPG for patient context and administration.</p></details><p class="caption">Packaged NZCPG exports: 24 September 2026. Reversible causes: ANZCOR 11.2. Local protocol takes precedence. This extracted app requires clinical validation before patient-care use.</p>`);}
function editEvent(id){const e=s.events.find(e=>e.id===id);if(!e)return;sheet('Correct event',`<form id="editForm"><p><b>${esc(e.title)}</b></p><label>Event time<input name="at" type="time" step="60" required value="${e.timeUnknown?'':local(e.at).slice(11)}"></label><label>Recorded details<textarea name="details">${esc(e.details)}</textarea></label>${['shock','noshock','rosc','rhythm'].includes(e.type)?`<label>Rhythm<select name="rhythm">${(e.type==='shock'?['Unknown','VF','VT','Torsades']:e.type==='noshock'?['PEA','Asystole','Other','Unknown']:e.type==='rosc'?['Sinus rhythm','Organised rhythm','AF','Other','Unknown']:['VF','VT','Torsades','PEA','Asystole','Sinus rhythm','Organised rhythm','AF','Other','Unknown']).map(r=>`<option ${e.rhythm===r?'selected':''}>${r}</option>`).join('')}</select></label>`:''}${['adrenaline','amiodarone','magnesium','fluids','medicine'].includes(e.type)?`<div class="inline-two"><label>Actual dose<input name="dose" type="number" step="any" min="0.001" value="${esc(e.dose||'')}" required></label><label>Unit<input name="unit" value="${esc(e.unit||'mg')}" required></label></div><label>Route<input name="route" value="${esc(e.route||'IV')}" required></label>`:''}${e.type==='shock'?`<label>Energy (J)<input name="energy" type="number" min="1" max="1000" inputmode="numeric" value="${esc(e.energy||'')}"></label>`:''}<button class="primary" type="submit">Save correction</button></form><p class="caption">Corrections update counters and medicine review clocks. They do not restart a CPR cycle. Original values are retained in JSON export.</p>${['start','pause','resume','rearrest','end','rosc'].includes(e.type)?'<p class="caption">To reverse a session state change, use Undo. State events cannot be voided here.</p>':`<button class="danger primary" data-void="${esc(id)}">${e.voided?'Restore event':'Void event · keep audit record'}</button>`}`,{kind:'edit',id});}
function exportText(){return logRows(false).map(e=>(e.timeUnknown?'Before app · time not set':time(e.at))+' '+e.title+(e.details?' — '+e.details:'')).join('\n');}
function download(content,type,ext){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download='resus-'+new Date(s.appStart).toISOString().replace(/[:.]/g,'-')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyLog(){
 const text=exportText();let copied=false;
 try{if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);copied=true;}}catch{}
 if(!copied){
  const field=document.createElement('textarea'),focus=document.activeElement;field.value=text;field.readOnly=true;field.setAttribute('aria-hidden','true');Object.assign(field.style,{position:'fixed',opacity:'0',pointerEvents:'none'});($('sheet').open?$('sheet'):document.body).append(field);
  try{field.select();field.setSelectionRange(0,text.length);copied=document.execCommand('copy');}catch{}finally{field.remove();focus?.focus();}
 }
 toast(copied?'Record copied':'Could not copy. Try again in your phone browser.');
}
function exportSheet(){sheet('Export event log',`<p>Save the record before starting a new patient or clearing browser data.</p><div class="stack"><button data-action="download-text">Download text record</button><button data-action="download-json">Download complete JSON + audit</button><button data-action="copy">Copy text record</button></div><p class="caption">Text export follows the current log filters, with hh:mm:ss and key details. Complete JSON retains all events, dates, timezone and audit history. Records stay on this device unless you export or share them.</p>`);}
async function keepAwake(){try{if(!('wakeLock' in navigator))return toast('Screen wake lock is unavailable in this browser.');if(wakeLock){await wakeLock.release();wakeLock=null;}else{wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null;});}openSettings();}catch{toast('Could not keep screen awake. Check device settings.');}}
function dateValue(form,now=Date.now()){const entered=form.get('at'),unknownEvent=sheetContext?.kind==='edit'?s.events.find(x=>x.id===sheetContext.id&&x.timeUnknown):null,original=sheetContext?.kind==='edit'?s.events.find(x=>x.id===sheetContext.id)?.at:sheetContext?.at;let at;if(unknownEvent){const d=new Date(local(s.appStart).slice(0,10)+'T'+entered);if(d.getTime()>=s.appStart)d.setDate(d.getDate()-1);at=d.getTime();}else if(original&&local(original).slice(11)===entered)at=original;else {const d=new Date(local(original||now).slice(0,10)+'T'+entered);if(sheetContext?.kind!=='edit'&&d.getTime()>now)d.setDate(d.getDate()-1);at=d.getTime();}if(!Number.isFinite(at)||at>now+1000){error('Enter a valid time that is not in the future.');return null;}return at;}
function syncRhythm(){const last=R.active(s).filter(e=>e.rhythm).sort((a,b)=>a.at-b.at).at(-1);s.rhythm=last?.rhythm||'Not recorded';}

document.addEventListener('click',async e=>{
 const b=e.target.closest('button,a[data-action]');if(!b)return;
 if(b.dataset.action)e.preventDefault();
 if(b.dataset.close!==undefined){closeSheet();return;}
 if(b.id==='undo'){s=R.undo(s);save();closeSheet();render();toast('Last action undone');return;}
 if(b.dataset.tab){if(b.dataset.tab==='checks'){checklist='arrest';checkReturn=tab==='guidance'?'guidance':'live';}tab=b.dataset.tab;render();window.scrollTo(0,0);return;}
 if(b.dataset.outcome){if(canRecord()){const outcome=b.dataset.outcome;if(outcome==='rosc')openRhythm(outcome);else if(R.startOutcome(s,outcome)){save();render();openRhythm(outcome);}}return;}
 if(b.dataset.recordRhythm){selectRhythm(b.dataset.recordRhythm);return;}
 if(b.hasAttribute('data-confirm-torsades')){const ctx=sheetContext;if(ctx?.kind==='torsades-confirm'&&ctx.session===s.id)saveRhythm(ctx.outcome,'Torsades',ctx.energy,ctx.at,ctx.eventId);return;}
 if(b.hasAttribute('data-back-rhythms')){const energy=sheetContext?.energy;openRhythm('shock');if($('shockEnergy'))$('shockEnergy').value=energy||'';return;}
 if(b.dataset.support){recordSupport(b.dataset.support);return;}
 if(b.hasAttribute('data-confirm-magnesium')){if(sheetContext?.kind==='repeat-magnesium')recordSupport('magnesium',true);return;}

 if(b.dataset.drug){if(!canRecord())return;const type=b.dataset.drug,value=drugDose(type);if(value===null||s.special||(type==='amiodarone'&&(torsades()||R.counts(s).amio>=2))||s.phase==='ROSC')return;commit(()=>R.add(s,type,type==='adrenaline'?'Adrenaline':'Amiodarone',value+' mg IV',Date.now(),{dose:value,unit:'mg',route:'IV',weightBasis:R.dose(s).basis,weight:s.weight,group:s.group}),'Recorded '+value+' mg IV · Undo available');return;}
 if(b.dataset.customDrug){if(canRecord())openDrug(b.dataset.customDrug);return;}
 if(b.dataset.drugInfo){administration(b.dataset.drugInfo);return;}
 if(b.dataset.checklist){checklist=b.dataset.checklist;render();return;}
 if(b.dataset.cause){if(!canRecord())return;if(b.dataset.status==='treated'){openNote(b.dataset.cause);return;}const cause=CAUSES.find(c=>c.id===b.dataset.cause);commit(()=>R.add(s,'cause',cause.name,b.dataset.status==='considered'?'Reviewed':'Suspected',Date.now(),{cause:cause.id,status:b.dataset.status}),'Cause review recorded');document.querySelector('[data-cause-id="'+cause.id+'"]').open=true;return;}
 if(b.dataset.equipment){if(canRecord())openEquipment(b.dataset.equipment);return;}
 if(b.dataset.reviewChecklist){checklist=b.dataset.reviewChecklist;checkReturn='log';tab='checks';render();return;}
 if(b.dataset.edit){editEvent(b.dataset.edit);return;}
 if(b.dataset.void){commit(()=>{const ev=s.events.find(x=>x.id===b.dataset.void);ev.audit=[...(ev.audit||[]),{at:Date.now(),before:JSON.parse(JSON.stringify({...ev,audit:undefined}))}];ev.voided=!ev.voided;ev.correctedAt=Date.now();syncRhythm();},'Event updated');closeSheet();return;}
 if(b.dataset.key){const input=$('weightInput'),k=b.dataset.key;if(sheetContext.replaceWeight&&k!=='⌫')input.value='';sheetContext.replaceWeight=false;input.value=k==='⌫'?input.value.slice(0,-1):k==='.'?(input.value.includes('.')?input.value:(input.value||'0')+'.'):(input.value==='0'?'':input.value)+k;weightChanged();return;}
 if(b.dataset.earlier){$('resusStartInput').value=local(s.appStart-Number(b.dataset.earlier)*60000);return;}
 if(b.dataset.checkStep){liveCheckIndex+=Number(b.dataset.checkStep);render();return;}
 const action=b.dataset.action;if(!action)return;
 if(action==='rhythm-check')openRhythmCheck();
 if(action==='arrest-checklist'){tab='checks';checklist='arrest';render();}
 if(action==='start'){if(!canRecord())return;commit(()=>{const now=Date.now();R.begin(s,now);R.add(s,'start','CPR cycle started','Cycle '+s.cycle,now);},'CPR cycle started');requestWakeSilently();}
 if(action==='pause'){const t=R.timing(s);if(s.phase!=='Active'||t.left===0)return;commit(()=>{const pause=s.deadline!==null;s.remaining=t.left;s.deadline=pause?null:Date.now()+t.left;R.add(s,pause?'pause':'resume',pause?'Cycle timer paused':'Cycle timer resumed');},'Cycle timer updated');}
 if(action==='rearrest'){if(s.phase!=='ROSC')return;commit(()=>{R.begin(s,Date.now());R.add(s,'rearrest','Re-arrest · CPR restarted');},'Re-arrest recorded');}
 if(action==='postrosc'){closeSheet();tab='checks';checklist='postrosc';checkReturn='live';render();}
 if(action==='previous-shock'&&canRecord())commit(()=>R.addPreAppShock(s),'Previous shock added');if(action==='explain-me')openExplainMe();if(action==='weight')openWeight();if(action==='cycle-log')openCycleLog();
 if(action==='resus-time')openResusTime();
 if(action==='settings')openSettings();
 if(action==='large'){s.largeText=!s.largeText;save();render();openSettings();}
 if(action==='wake')await keepAwake();
 if(action==='history')openHistory();
 if(action==='guidance'){closeSheet();tab='guidance';render();}
 if(action==='interventions')openInterventions();if(action==='airway'||action==='access')openInterventions(action);
 if(action==='note'){if(canRecord())openNote();}
 if(action==='rhythm'){sheet('Record rhythm only',`<p class="caption">Updates the observed rhythm without adding a shock, no-shock cycle or ROSC.</p><div class="choice-grid">${['VF','VT','Torsades','PEA','Asystole','Sinus rhythm','Organised rhythm','AF','Unknown','Other'].map(r=>`<button data-only-rhythm="${r}">${r==='VT'?'Pulseless VT':r}</button>`).join('')}</div>`);}
 if(action==='estimate'){const w=R.estimate($('ageInput').value);if(w===null)return error('Use an infant age in years or whole years 1–14.');$('weightInput').value=w;$('weightPadPrompt').hidden=!R.needsPaediatricPads(w);sheetContext.source='Estimated from age '+$('ageInput').value+' years · CPG 7.2';$('weightBasis').innerHTML=formatGuidelineReference(sheetContext.source);}
 if(action==='save-weight'){const w=$('weightInput').value.replace(',','.');if(!R.validWeight(w))return error('Enter weight above zero and no more than 500 kg, with up to one decimal.');const source=sheetContext.source,age=$('ageInput').value;commit(()=>{Object.assign(s,{weight:String(+w),group:+w<=40?'Child':'Adult',weightSource:source,age});delete s.adultConfirmed;R.add(s,'weight','Patient weight updated',w+' kg · '+source);},'Weight reference updated');closeSheet();}
 if(action==='save-resus-time'){const at=new Date($('resusStartInput').value).getTime();if(!Number.isFinite(at)||at>s.appStart)return error('Resus start must be at or before the app session start.');commit(()=>{const prev=s.resusStart;s.resusStart=at;R.add(s,'resus-time','Resus start corrected',new Date(prev).toISOString()+' → '+new Date(at).toISOString());},'Resus duration updated');closeSheet();}
 if(action==='save-history'){const vals=Object.fromEntries(['priorShocks','priorNoShock','priorStreak','priorAmio'].map(k=>[k,Number($(k).value)]));if(Object.values(vals).some(v=>!Number.isInteger(v)||v<0||v>100)||vals.priorStreak>vals.priorNoShock)return error('Use whole numbers 0–100. Consecutive cycles cannot exceed the prior total.');commit(()=>{Object.assign(s,vals);R.add(s,'history','Earlier counts updated',vals.priorShocks+' shocks · '+vals.priorNoShock+' no-shock cycles · '+vals.priorAmio+' amiodarone doses');},'Earlier counts saved');closeSheet();}
 if(action==='export')exportSheet();
 if(action==='download-text')download(exportText(),'text/plain','txt');
 if(action==='download-json'){const data={...s,undo:undefined,exportedAt:new Date().toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};download(JSON.stringify(data,null,2),'application/json','json');}
 if(action==='copy')await copyLog();
 if(action==='end')sheet('End resuscitation session?',`<p>This stops the cycle and resus clocks. Your event log is kept.</p><button class="primary danger" data-action="confirm-end">End session now</button><button class="primary" data-close>Keep recording</button>`);
 if(action==='confirm-end'){commit(()=>{const now=Date.now();s.remaining=R.timing(s,now).left;s.phase='Ended';s.deadline=null;s.end=now;R.add(s,'end','Session ended','',now);},'Session ended · log kept');closeSheet();}
 if(action==='new')sheet('Start a new patient?',`<p>The current record will be cleared from this browser. Export it first if you need to keep it.</p><button class="primary" data-action="export">Export current record</button><button class="primary danger" data-action="confirm-new">Clear record & start new patient</button>`);
 if(action==='confirm-new'){const large=s.largeText;s=R.fresh();s.largeText=large;tab='live';liveCheckIndex=0;logScope='all';checklistDisplay='items';save();closeSheet();render();toast('New patient · clocks started');}
 if(action==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else sheet('Add to home screen',`<p><b>Android / Chrome:</b> open the browser menu, then choose “Add to Home screen” or “Install app”.</p><p><b>iPhone / Safari:</b> tap Share, then “Add to Home Screen”.</p><p class="caption">Open this site in your phone browser first. Offline files are prepared after the first successful load. Browser or device suspension can delay screen updates; clocks catch up on return. No background alarm is guaranteed.</p>`);}
});
document.addEventListener('click',e=>{const b=e.target.closest('[data-only-rhythm]');if(!b||!canRecord())return;commit(()=>{s.rhythm=b.dataset.onlyRhythm;R.add(s,'rhythm','Rhythm recorded',s.rhythm,Date.now(),{rhythm:s.rhythm});},'Rhythm recorded');closeSheet();});
function weightChanged(){const w=$('weightInput').value.replace(',','.');$('weightPadPrompt').hidden=!R.needsPaediatricPads(w);sheetContext.source='Entered';$('weightBasis').textContent='Entered';}
document.addEventListener('input',e=>{if(e.target.id==='weightInput')weightChanged();if(e.target.dataset.size){const type=e.target.dataset.size,unit=document.querySelector('[name=sizeUnit]:checked')?.value||'mm',sizes=ARREST_EQUIPMENT[type].sizes.filter(v=>type!=='npa'||v.endsWith(unit)),value=sizes[+e.target.value];document.querySelector('#equipmentForm [name=size]').value=value;$('sizeRead').textContent=value+(type==='iv'?'G':'');equipmentFeedback(e);}});
document.addEventListener('change',e=>{
 if(e.target.id==='logScope'){logScope=e.target.value;render();return;}
 if(e.target.id==='checklistDisplay'){checklistDisplay=e.target.value;render();return;}
 if(e.target.dataset.check){const key=e.target.dataset.check,checked=e.target.checked,[id,i]=key.split(':'),list=ARREST_CHECKLISTS.find(c=>c.id===id);commit(()=>{R.add(s,'checklist',list.label,(checked?'Checked: ':'Unmarked: ')+list.items[+i],Date.now(),{key,checked});if(tab==='live'&&checked&&id==='arrest'){const next=list.items.findIndex((_,j)=>j>+i&&!checkStatus('arrest:'+j)?.checked);if(next>=0)liveCheckIndex=next;}});}
 if(e.target.id==='specialInput'){commit(()=>{s.special=e.target.checked;R.add(s,'context','Special situation mode',s.special?'Routine prompts disabled':'Routine prompts enabled');});}
 if(e.target.name==='sizeUnit'){const sizes=ARREST_EQUIPMENT.npa.sizes.filter(v=>v.endsWith(e.target.value)),range=document.querySelector('[data-size=npa]');range.max=sizes.length-1;range.value=0;document.querySelector('#equipmentForm [name=size]').value='';$('sizeRead').textContent='Not recorded';$('sizeRange').textContent=sizes[0]+' – '+sizes.at(-1);}
});
document.addEventListener('submit',e=>{
 if(!['drugForm','equipmentForm','noteForm','editForm'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target),at=dateValue(f);if(at===null)return;
 if(e.target.id==='drugForm'){if(!canRecord())return;const name=f.get('name').trim(),dose=+f.get('dose'),unit=f.get('unit'),route=f.get('route');if(!name||!Number.isFinite(dose)||dose<=0||!route)return error('Enter medicine, actual dose and route.');const type=name.toLowerCase()==='adrenaline'?'adrenaline':name.toLowerCase()==='amiodarone'?'amiodarone':name.toLowerCase()==='magnesium'?'magnesium':name.toLowerCase()==='0.9% sodium chloride'?'fluids':'medicine';commit(()=>R.add(s,type,name,dose+' '+unit+' '+route+(f.get('notes')?' · '+f.get('notes'):''),at,{dose,unit,route,notes:f.get('notes')}),'Administration recorded');closeSheet();}
 if(e.target.id==='equipmentForm'){if(!canRecord())return;const type=sheetContext.type,data=Object.fromEntries(f);if(data.side&&data.site)data.site=data.side+' '+data.site;const confirmed=f.getAll('confirmation');if(type==='intubation'&&data.size&&(!Number.isFinite(+data.size)||+data.size<=0||+data.size>12))return error('Enter a valid tube size in mm.');const parts=Object.entries(data).filter(([k,v])=>!['at','confirmation','sizeUnit','side'].includes(k)&&v).map(([k,v])=>k+': '+v);if(!data.size)parts.unshift('Size not recorded');if(type==='intubation')parts.push(confirmed.length?'Confirmed with: '+confirmed.join(', '):'Confirmation not recorded');commit(()=>R.add(s,'equipment',ARREST_EQUIPMENT[type].name,parts.join(' · '),at,{procedure:type,equipment:{...data,confirmation:confirmed}}),'Intervention recorded');closeSheet();if(type==='laryngoscopy'&&e.submitter?.value==='intubation')openEquipment('intubation');}
 if(e.target.id==='noteForm'){if(!canRecord())return;const text=f.get('text').trim(),cause=sheetContext.cause;if(!text)return error('Enter the event or action.');commit(()=>R.add(s,cause?'cause':'note',cause?CAUSES.find(c=>c.id===cause).name+' · action':'Event',text,at,cause?{cause,status:'treated'}:{}),'Event recorded');closeSheet();}
 if(e.target.id==='editForm'){const ev=s.events.find(x=>x.id===sheetContext.id);if(ev.preApp&&at>=s.appStart)return error('Use a time before the app opened.');if(['start','pause','resume','rearrest','end','rosc'].includes(ev.type)&&local(at)!==local(ev.at))return error('State-change times cannot be changed here. Undo and re-record the state change.');const dose=f.has('dose')?+f.get('dose'):null;if(f.has('dose')&&(!Number.isFinite(dose)||dose<=0))return error('Enter a positive actual dose.');commit(()=>{ev.audit=[...(ev.audit||[]),{at:Date.now(),before:JSON.parse(JSON.stringify({...ev,audit:undefined}))}];ev.at=at;ev.details=f.get('details');if(ev.type==='equipment')delete ev.equipment;ev.correctedAt=Date.now();if(ev.preApp){ev.needsReview=false;delete ev.timeUnknown;}if(f.has('rhythm'))ev.rhythm=f.get('rhythm');if(f.has('dose')){ev.dose=dose;ev.unit=f.get('unit');ev.route=f.get('route');ev.details=dose+' '+ev.unit+' '+ev.route+(ev.notes?' · '+ev.notes:'');}if(f.has('energy'))ev.energy=f.get('energy');if(['shock','noshock','rosc','rhythm'].includes(ev.type))ev.details=ev.rhythm+(ev.type==='shock'?' · '+(ev.energy?ev.energy+' J':'energy not recorded'):'');syncRhythm();},'Event corrected');closeSheet();}
});
async function requestWakeSilently(){try{if('wakeLock' in navigator&&!wakeLock)wakeLock=await navigator.wakeLock.request('screen');}catch{}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();if(s.phase==='Active')requestWakeSilently();}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
$('sheet').addEventListener('cancel',()=>sheetContext=null);
save();render();setInterval(tick,250);

// Replace a confirmed weight on the first typed/pasted digit, just like the keypad.
document.addEventListener('beforeinput',e=>{
 if(e.target.id!=='weightInput'||sheetContext?.kind!=='weight')return;
 if(sheetContext.replaceWeight&&e.inputType?.startsWith('insert')){e.target.value='';e.target.setSelectionRange(0,0);}
 sheetContext.replaceWeight=false;
});
// Dismiss airway/access menus only when the backdrop itself is tapped.
$('sheet').addEventListener('click',e=>{
 if(e.target!==$('sheet')||!['equipment','interventions'].includes(sheetContext?.kind))return;
 const r=$('sheet').getBoundingClientRect();
 if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeSheet();
});

const CARDIAC_CPG='https://cpg.stjohn.org.nz/tabs/guidelines/cardiac-eas/page/cardiac-arrest-eas';
const MAGNESIUM_CPG='https://cpg.stjohn.org.nz/tabs/medicines/page/magnesium-sulphate-eas';
function supportCard(type){
 const mag=type==='magnesium',ref=mag?R.magnesiumReference(s):R.fluidReference(s),stats=R.supportStats(s,type),value=mag?(ref.dose===null?'Dose: clinical review':ref.dose+' mmol IV'):(ref.min===null?'Enter weight':ref.min+'–'+ref.max+' mL IV');
 const enabled=!s.special&&!['ROSC','Ended'].includes(s.phase),canRef=enabled&&(!mag||(ref.dose!==null&&stats.count<2));
 const label=mag?(stats.count>=2?'2 doses recorded':ref.dose===null?'Review dose':stats.count?'Record repeat…':'Record '+ref.dose+' mmol IV'):'Record fluid…';
 return `<section class="drug ${type}" id="${type}Card"><h3>${mag?'Magnesium':'Fluids · NaCl 0.9%'}</h3><div class="drug-dose">${esc(value)}</div><strong class="drug-clock" id="supportClock">—</strong><p class="caption" id="supportStatus"></p><button class="record" data-support="${type}" ${canRef?'':'disabled'}>${enabled?label:s.phase==='ROSC'?'ROSC recorded':s.phase==='Ended'?'Session ended':'Manual review'}</button><div class="drug-links"><button class="administration-link" data-drug-info="${type}">Administration ⓘ</button><button class="alternate" data-custom-drug="${type}">Other…</button></div></section>`;
}
function tickSupport(type,enabled){const stats=R.supportStats(s,type);$('supportClock').textContent=stats.last?clock(Date.now()-stats.last.at):'—';$('supportStatus').textContent=!enabled?'Review inactive':type==='magnesium'?(stats.count>=2?'2 doses · clinical review':stats.count?'Repeat once only if TdP persists/recurs':'Withhold amiodarone · torsades history'):(stats.total?stats.total+' mL recorded · review total':'PEA · review fluid volume');}
function cpgSource(){return `<p class="caption">NZCPG <em>EAS guideline 3.14</em><br><a href="${CARDIAC_CPG}" target="_blank" rel="noopener">Current <em>EAS guideline 3.14</em> ↗</a> · <a href="https://cpg.stjohn.org.nz/tabs/guidelines/cardiac-eas/page/cardiac-arrest-eas#page=2" target="_blank">Source <em>EAS guideline 3.14</em> ↗</a></p>`;}
function torsadesSnippet(){return `<div class="rhythm-snippet"><h3>Torsades de pointes · guideline extract</h3><blockquote>Withhold amiodarone.<br>Administer magnesium IV:</blockquote><p>Adult reference: 10 mmol (2.5 g), given IV over 1–2 minutes. A single repeat is permitted when torsades continues or returns. Use the paediatric dose tables for children.</p></div>${cpgSource()}`;}
function peaSnippet(){return `<div class="rhythm-snippet"><h3>PEA · guideline extract</h3><blockquote>Correct immediately reversible causes.<br>Administer 0.9% sodium chloride IV:</blockquote><p>The IV volume reference is 1–2 L in adults, or 20–40 mL/kg in children. Assess and treat the reversible cause.</p></div>${cpgSource()}`;}
function supportAdministration(type){
 if(type==='fluids'){const ref=R.fluidReference(s);sheet('Fluids · administration',`${peaSnippet()}<p><b>${ref.min===null?'Enter weight':ref.min+'–'+ref.max+' mL IV'}</b> · ${formatGuidelineReference(ref.basis)}</p><p>Record the actual volume given in mL. The card shows the recorded total; a rhythm change does not record fluid administration.</p>`);return;}
 const ref=R.magnesiumReference(s);
 sheet('Magnesium · administration',`${torsadesSnippet()}<p><b>${ref.dose===null?'Dose requires clinical review':ref.dose+' mmol IV'}</b> · ${formatGuidelineReference(ref.basis)}</p><p>For adult cardiac-arrest administration, dilute the 10 mmol dose with 0.9% sodium chloride to 10 mL and give over 1–2 minutes. The paediatric preparation in <em>EAS guideline 7.2</em> is 1 mmol/mL: dilute 5 mL from a 10 mmol/5 mL ampoule to 10 mL, then draw up the table dose.</p><p>Avoid the IV line carrying a concurrent adrenaline infusion because precipitation can occur. Record magnesium in mmol.</p><a href="${MAGNESIUM_CPG}" target="_blank" rel="noopener"><em>EAS guideline 14.27</em> ↗</a><p><a href="https://cpg.stjohn.org.nz/tabs/guidelines/paediatrics-eas/page/paediatric-equipment-and-drug-doses-eas" target="_blank"><em>EAS guideline 7.2</em> ↗</a></p>`);
}
function recordSupport(type,confirmed=false){
 if(!canRecord()||s.special||['ROSC','Ended'].includes(s.phase)||R.careMode(s)!==type)return;
 if(type==='fluids'){openDrug('fluids');return;}
 const ref=R.magnesiumReference(s),stats=R.supportStats(s,type);if(ref.dose===null||stats.count>=2)return;
 if(stats.count&&!confirmed){sheet('Repeat magnesium?',`${torsadesSnippet()}<p>One dose is already recorded. Record a second dose only if it was given for persistent or recurrent torsades.</p><button class="primary" data-confirm-magnesium>Record repeat ${ref.dose} mmol IV</button><button class="primary" data-close>Back</button>`,{kind:'repeat-magnesium'});return;}
 commit(()=>R.add(s,'magnesium','Magnesium',ref.dose+' mmol IV',Date.now(),{dose:ref.dose,unit:'mmol',route:'IV',weight:s.weight,weightBasis:ref.basis}),'Magnesium recorded · Undo available');closeSheet();
}
function saveRhythm(outcome,rhythm,energy,at=Date.now(),eventId=sheetContext?.eventId){
 if(!canRecord())return false;
 if(!(eventId?R.completeOutcome(s,eventId,rhythm,energy):outcome==='rosc'&&R.check(s,outcome,rhythm,energy,at))){error('Check the recorded energy.');return false;}
 const rosc=outcome==='rosc';save();closeSheet();if(rosc){tab='checks';checklist='postrosc';checkReturn='live';}render();toast(rosc?'ROSC recorded · clocks stopped':'Rhythm recorded');return true;
}
function selectRhythm(rhythm){
 const ctx=sheetContext;if(ctx?.kind!=='rhythm')return;
 const energy=$('shockEnergy')?.value||'',outcome=ctx.outcome;
 if(rhythm==='Torsades'&&outcome==='shock'){
  if(energy!==''&&(!Number.isFinite(+energy)||+energy<=0||+energy>1000)){error('Check the recorded energy.');return;}
  sheet('Confirm Torsades',`${torsadesSnippet()}<p>Confirm the observed rhythm to record the delivered shock. This does not record a magnesium administration.</p><button class="primary" data-confirm-torsades>Confirm Torsades</button><button class="primary" data-back-rhythms>Back to rhythms</button>`,{kind:'torsades-confirm',outcome,energy,at:Date.now(),session:s.id,eventId:ctx.eventId});return;
 }
 if(saveRhythm(outcome,rhythm,energy)&&rhythm==='PEA')sheet('PEA · fluid guidance',`${peaSnippet()}<button class="primary" data-close>Continue CPR</button>`);
}
function rhythmImages(){return `<div class="rhythm-image-choices">${[['VF','Ventricular fibrillation'],['VT','Pulseless VT'],['Torsades','Torsades de pointes']].map(([id,title])=>`<button data-record-rhythm="${id}">${title}</button>`).join('')}</div>`;}
if(s.pendingRhythm)openRhythm(s.pendingRhythm.outcome);

function formatGuidelineReference(value){return esc(value).replace(/\b(EAS|CPG|ANZCOR)(?: guideline)?\s+(\d+\.\d+)/g,(_,issuer,number)=>'<em>'+(issuer==='ANZCOR'?'ANZCOR':'EAS')+' guideline '+number+'</em>');}
function normalizeGuidelineReferences(root){
 const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),nodes=[];let node;
 while((node=walker.nextNode()))if(!node.parentElement.closest('em,script,style,textarea,code,pre'))nodes.push(node);
 for(const textNode of nodes){
  const text=textNode.nodeValue,re=/\b(EAS|CPG|ANZCOR)(?: guideline)?\s+(\d+\.\d+(?:\s*(?:\/|and|,)\s*\d+\.\d+)*)/g;let m,last=0,fragment=document.createDocumentFragment(),found=false;
  while((m=re.exec(text))){found=true;fragment.append(document.createTextNode(text.slice(last,m.index)));const issuer=m[1]==='ANZCOR'?'ANZCOR':'EAS',parts=m[2].split(/(\s*(?:\/|and|,)\s*)/);
   for(const part of parts){if(/^\d/.test(part)){const em=document.createElement('em');em.textContent=issuer+' guideline '+part;fragment.append(em);}else fragment.append(document.createTextNode(part));}last=re.lastIndex;
  }
  if(found){fragment.append(document.createTextNode(text.slice(last)));textNode.replaceWith(fragment);}
 }
}
